#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstdio>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    vector<char> c(n);
    vector<int> x(n), y(n);

    for (int i = 0; i < n; ++i)
        scanf(" %c%d%d", &c[i], &x[i], &y[i]);

    const int W = 121;
    const uint8_t UNREACHABLE = 255;
    const int states = 1 << n;

    vector<uint8_t> dp(static_cast<size_t>(states) * W, UNREACHABLE);
    dp[0] = 0;

    for (int mask = 0; mask < states; ++mask) {
        int A = 0, B = 0;

        for (int k = 0; k < n; ++k) {
            if (mask & (1 << k)) {
                if (c[k] == 'R')
                    ++A;
                else
                    ++B;
            }
        }

        const size_t base = static_cast<size_t>(mask) * W;

        for (int k = 0; k < n; ++k) {
            if (mask & (1 << k))
                continue;

            const int nextMask = mask | (1 << k);
            const size_t nextBase = static_cast<size_t>(nextMask) * W;
            const int addX = min(x[k], A);
            const int addY = min(y[k], B);

            for (int j = 0; j < W; ++j) {
                if (dp[base + j] == UNREACHABLE || j + addX >= W)
                    continue;

                uint8_t &dest = dp[nextBase + j + addX];
                dest = max<int>(dest == UNREACHABLE ? 0 : dest,
                                dp[base + j] + addY);
            }
        }
    }

    int X = 0, Y = 0;
    for (int i = 0; i < n; ++i) {
        X += x[i];
        Y += y[i];
    }

    int ans = 0x3f3f3f3f;
    const size_t finalBase = static_cast<size_t>(states - 1) * W;

    for (int i = 0; i < W; ++i) {
        if (dp[finalBase + i] != UNREACHABLE)
            ans = min(ans, max(X - i, Y - static_cast<int>(dp[finalBase + i])));
    }

    printf("%d\n", ans + n);
    return 0;
}

#include <iostream>
