using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    vector<char> c(n);
    vector<int> x(n), y(n);

    unsigned int redMask = 0;
    int X = 0, Y = 0;

    for (int i = 0; i < n; ++i) {
        scanf(" %c%d%d", &c[i], &x[i], &y[i]);
        if (c[i] == 'R') redMask |= 1U << i;
        X += x[i];
        Y += y[i];
    }

    const int W = 121;
    const uint8_t UNREACHABLE = 255;
    const size_t states = size_t(1) << n;

    vector<uint8_t> dp(states * W, UNREACHABLE);
    dp[0] = 0;

    for (size_t mask = 0; mask + 1 < states; ++mask) {
        unsigned int m = static_cast<unsigned int>(mask);
        int A = __builtin_popcount(m & redMask);
        int B = __builtin_popcount(m) - A;
        size_t base = mask * W;

        for (int k = 0; k < n; ++k) {
            if (m & (1U << k)) continue;

            int addX = min(x[k], A);
            int addY = min(y[k], B);
            if (addX > 120) continue;

            size_t nextBase = (mask | (size_t(1) << k)) * W;

            for (int j = 0; j + addX <= 120; ++j) {
                uint8_t value = dp[base + j];
                if (value == UNREACHABLE) continue;

                uint8_t &target = dp[nextBase + j + addX];
                int candidate = static_cast<int>(value) + addY;
                if (candidate > target || target == UNREACHABLE)
                    target = static_cast<uint8_t>(candidate);
            }
        }
    }

    int answer = 0x3f3f3f3f;
    size_t finalBase = (states - 1) * W;

    for (int i = 0; i <= 120; ++i) {
        uint8_t value = dp[finalBase + i];
        if (value != UNREACHABLE)
            answer = min(answer, max(X - i, Y - static_cast<int>(value)));
    }

    printf("%d\n", answer + n);
    return 0;
}

