    unsigned int redMask = 0;

    for (int i = 0; i < n; ++i) {
        scanf(" %c%d%d", &c[i], &x[i], &y[i]);
        X += x[i];
        Y += y[i];
        if (c[i] == 'R') redMask |= 1u << i;
    }

    const int limit = min(X, 120);
    const int width = limit + 1;
    const unsigned int states = 1u << n;
    const uint8_t UNREACHABLE = 255;

    vector<uint8_t> dp(static_cast<size_t>(states) * width, UNREACHABLE);
    dp[0] = 0;

    for (unsigned int mask = 0; mask + 1 < states; ++mask) {
        int A = __builtin_popcount(mask & redMask);
        int B = __builtin_popcount(mask) - A;
        size_t base = static_cast<size_t>(mask) * width;

        for (int k = 0; k < n; ++k) {
            unsigned int bit = 1u << k;
            if (mask & bit) continue;

            unsigned int nextMask = mask | bit;
            size_t nextBase = static_cast<size_t>(nextMask) * width;
            int addX = min(x[k], A);
            int addY = min(y[k], B);

            for (int j = 0; j + addX <= limit; ++j) {
                uint8_t value = dp[base + j];
                if (value == UNREACHABLE) continue;

                int nextValue = static_cast<int>(value) + addY;
                uint8_t &destination = dp[nextBase + j + addX];
                if (nextValue > destination || destination == UNREACHABLE)
                    destination = static_cast<uint8_t>(nextValue);
            }
        }
    }

    int answer = INT_MAX;
    size_t finalBase = static_cast<size_t>(states - 1) * width;

    for (int i = 0; i <= limit; ++i) {
        uint8_t value = dp[finalBase + i];
        if (value != UNREACHABLE)
            answer = min(answer, max(X - i, Y - static_cast<int>(value)));
    }

    printf("%d\n", answer + n);
    return 0;
}

#include <cstdio>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    vector<char> c(n);
    vector<int> x(n), y(n);

    unsigned redMask = 0;
    for (int i = 0; i < n; ++i) {
        scanf(" %c%d%d", &c[i], &x[i], &y[i]);
        if (c[i] == 'R') redMask |= 1u << i;
    }

    const int LIMIT = 120;
    const int WIDTH = LIMIT + 1;
    const unsigned states = 1u << n;
    const uint8_t UNREACHABLE = 255;

    vector<uint8_t> dp(static_cast<size_t>(states) * WIDTH, UNREACHABLE);
    dp[0] = 0;

    for (unsigned mask = 0; mask < states; ++mask) {
        int A = __builtin_popcount(mask & redMask);
        int B = __builtin_popcount(mask & ~redMask);

        const size_t current = static_cast<size_t>(mask) * WIDTH;

        for (int k = 0; k < n; ++k) {
            if (mask & (1u << k)) continue;

            unsigned nextMask = mask | (1u << k);
            size_t next = static_cast<size_t>(nextMask) * WIDTH;
            int addX = min(x[k], A);
            int addY = min(y[k], B);

            for (int j = 0; j + addX <= LIMIT; ++j) {
                uint8_t value = dp[current + j];
                if (value == UNREACHABLE) continue;

                int candidate = static_cast<int>(value) + addY;
                uint8_t &destination = dp[next + j + addX];
                if (destination == UNREACHABLE || candidate > destination)
                    destination = static_cast<uint8_t>(candidate);
            }
        }
    }

    int totalX = 0, totalY = 0;
    for (int i = 0; i < n; ++i) {
        totalX += x[i];
        totalY += y[i];
    }

    int answer = max(totalX, totalY);
    size_t finalState = static_cast<size_t>(states - 1) * WIDTH;

    for (int savedX = 0; savedX <= LIMIT; ++savedX) {
        uint8_t savedY = dp[finalState + savedX];
        if (savedY != UNREACHABLE) {
            answer = min(answer,
                         max(totalX - savedX,
                             totalY - static_cast<int>(savedY)));
        }
    }

    printf("%d\n", answer + n);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<char> c(n);
    vector<int> x(n), y(n);
    for (int i = 0; i < n; ++i)
        cin >> c[i] >> x[i] >> y[i];

    constexpr int MAX_DISCOUNT = 120;
    constexpr uint8_t UNREACHABLE = 255;

    const int states = 1 << n;
    vector<uint8_t> dp(static_cast<size_t>(states) * (MAX_DISCOUNT + 1),
                       UNREACHABLE);

    auto at = [&](int mask, int discount) -> uint8_t& {
        return dp[static_cast<size_t>(mask) * (MAX_DISCOUNT + 1) + discount];
    };

    at(0, 0) = 0;

    for (int mask = 0; mask < states - 1; ++mask) {
        int red = 0, blue = 0;
        for (int k = 0; k < n; ++k) {
            if (mask & (1 << k)) {
                if (c[k] == 'R') ++red;
                else ++blue;
            }
        }

        for (int k = 0; k < n; ++k) {
            if (mask & (1 << k)) continue;

            const int nextMask = mask | (1 << k);
            const int addX = min(x[k], red);
            const int addY = min(y[k], blue);

            for (int j = 0; j + addX <= MAX_DISCOUNT; ++j) {
                const uint8_t current = at(mask, j);
                if (current == UNREACHABLE) continue;

                uint8_t& next = at(nextMask, j + addX);
                next = max<int>(next == UNREACHABLE ? 0 : next,
                                static_cast<int>(current) + addY);
            }
        }
    }

    int totalX = 0, totalY = 0;
    for (int i = 0; i < n; ++i) {
        totalX += x[i];
        totalY += y[i];
    }

    int answer = 1e9;
    for (int i = 0; i <= MAX_DISCOUNT; ++i) {
        const uint8_t value = at(states - 1, i);
        if (value != UNREACHABLE)
            answer = min(answer, max(totalX - i, totalY - static_cast<int>(value)));
    }

    cout << answer + n << '\n';
    return 0;
}

